(7700407, 1263586, 4008, '<td valign="top">I love the soft light and the almost black and white feel contrasted by the blue eyes and red lips. The face seems a bit overprocessed, seems less sharp than for example the feathers. I don''t like the shadow of her head on the background.</td>', 'I love the soft light and the almost black and white feel contrasted by the blue eyes and red lips. The face seems a bit overprocessed, seems less sharp than for example the feathers. I don''t like the shadow of her head on the background.', '2021-09-04 08:06:29.000000', NULL, 1),
(7700408, 1263856, 4008, '<td valign="top">Great to have the people in the frame.</td>', 'Great to have the people in the frame.', '2021-09-04 08:07:24.000000', NULL, 1),
(7700409, 1263838, 4008, '<td valign="top">Great portrait, beautiful soft light but still enough tonal variation. The color of her top matching her eyes is great. The background seems added digitally? The edges seem wrong and I see rings in the background light.</td>', 'Great portrait, beautiful soft light but still enough tonal variation. The color of her top matching her eyes is great. The background seems added digitally? The edges seem wrong and I see rings in the background light.', '2021-09-04 08:07:47.000000', NULL, 1),
(7700410, 1263957, 4008, '<td valign="top">Does not look totally sharp, also not the front one. (and I have seen so many similar images in the past months that I start to get a bit tired of them).</td>', 'Does not look totally sharp, also not the front one. (and I have seen so many similar images in the past months that I start to get a bit tired of them).', '2021-09-04 08:10:03.000000', NULL, 1),
